db:select.db:sql:
select customer_id, name, to_char(birth_date, 'YYYY-MM-DD') as birth_date, occupation, to_char(opened_on, 'YYYY-MM-DD') as opened_on
                    from max.customers where split_part(name, ' ', 1) = split_part(:n, ' ', 1) or split_part(name, ' ', 2) = split_part(:n, ' ', 2)
                    order by customer_id

mcp:tool-listener.mcp:parameters-schema:
{
  "type": "object",
  "properties": {
    "status": {"type": "string", "description": "Only applications in this status, e.g. 確認待ち. Empty or missing for all."}
  }
}

set-variable.value:
#[do {
            var raw = trim(payload.applicationId default '')
            var digits = raw replace /^(?i)OA-?/ with ''
            ---
            if (digits matches /\d{1,4}/) 'OA-' ++ ((digits as Number) as String {format: '0000'}) else raw}]

mcp:tool-listener.mcp:parameters-schema:
{
  "type": "object",
  "properties": {
    "contextId": {"type": "string", "description": "The conversation (A2A contextId)"},
    "applicationId": {"type": "string", "description": "Application ID such as OA-0003"},
    "recommendation": {"type": "string", "enum": ["承認", "否認", "追加確認"]},
    "facts": {"type": "string", "description": "The applicant, 2 to 4 lines"},
    "findings": {"type": "string", "description": "The rules tripped and what was found, one per line"},
    "gaps": {"type": "string", "description": "What could not be checked"},
    "reasoning": {"type": "string", "description": "Why this recommendation, 2 to 4 sentences"}
  },
  "required": ["contextId", "applicationId", "recommendation", "facts", "reasoning"]
}
